  SelectValue,
} from '#/components/ui/select'
import {
  listMarketSources,
  marketAdd,
  marketBook,
  marketBrowse,
} from '#/lib/market-functions'
import { mergeBooks, mergeHome, mergeShelves } from '#/lib/market/merge'
import type { MergedBook, MergedShelf, SourceRef } from '#/lib/market/merge'
import type { BookDetails } from '#/lib/market/sdk'

type MarketSearch = { q?: string; shelf?: SourceRef[] }

// The router parses values as JSON, so a numeric query arrives as a number.
function validateShelf(value: unknown) {
  if (!Array.isArray(value)) return undefined
  const refs = value.flatMap((r: Record<string, unknown>) =>
    Number(r?.source) && typeof r?.id === 'string'
      ? [{ source: Number(r.source), id: r.id }]
      : [],
  )
  return refs.length ? refs : undefined
}

type Source = Awaited<ReturnType<typeof listMarketSources>>[number]
type InLibrary = Record<string, string>

// Browses every source set up in Settings → Market sources at once: their
// homes, a shelf (`shelf`: one id per source, for shelves merged by name) or
// search results (`q`). The same book from several sources is shown once.
export const Route = createFileRoute('/_app/market')({
  beforeLoad: ({ context }) => {
    if (context.user.role !== 'admin') throw redirect({ to: '/' })
  },
  validateSearch: (search: Record<string, unknown>): MarketSearch => ({
    q:
      typeof search.q === 'string' || typeof search.q === 'number'
        ? String(search.q)
        : undefined,
    shelf: validateShelf(search.shelf),
  }),
  loader: () => listMarketSources(),
  component: Market,
})

type Answer = {
  source: Source
  view: Awaited<ReturnType<typeof marketBrowse>> | null
  error: string | null
}

type MarketState = {
  loading: boolean
  errors: Array<{ source: number; sourceName: string; error: string }>
  home: ReturnType<typeof mergeHome> | null
  title: string | null
  shelves: MergedShelf[]
  books: MergedBook[]
  // The next page's cursor per source id. A source that fails keeps its
  // cursor, so "Load more" retries it.
  cursors: Record<number, string>
}

const EMPTY: MarketState = {
  loading: true,
  errors: [],
  home: null,
  title: null,
  shelves: [],
  books: [],
  cursors: {},
}

const message = (err: unknown) =>
  err instanceof Error ? err.message : 'Request failed'

// Adds a batch of answers, one per source asked, to what is shown.
function settle(
  prev: MarketState,
  answers: Answer[],
  q: string | undefined,
): MarketState {
  const listings = answers.flatMap((a) =>
    a.view?.kind === 'listing'
      ? [{ source: a.source.id, sourceName: a.source.name, ...a.view.listing }]
      : [],
  )
  const homes = answers.flatMap((a) =>
    a.view?.kind === 'home'
      ? [{ source: a.source.id, sourceName: a.source.name, ...a.view.home }]
      : [],
  )
  const cursors = { ...prev.cursors }
  for (const l of listings) {
    if (l.nextCursor) cursors[l.source] = l.nextCursor
    else delete cursors[l.source]
  }
  return {
    loading: false,
    errors: answers.flatMap((a) =>
      a.error
        ? [{ source: a.source.id, sourceName: a.source.name, error: a.error }]
        : [],
    ),
    home: homes.length ? mergeHome(homes) : prev.home,
    title: prev.title ?? listings[0]?.title ?? null,
    shelves: prev.shelves.length
      ? prev.shelves
      : mergeShelves(listings.map((l) => ({ ...l, items: l.shelves }))),
    books: mergeBooks(
      prev.books,
      listings.map((l) => ({ ...l, items: l.books })),
      q,
    ),
    cursors,
  }
}

// Loads the view from every source and shows them together once all have
// answered, so nothing moves when a slow source arrives; "Load more" adds the
// next page from each the same way. Which books are in the library is kept
// for every offer seen, so adding a book shows everywhere it appears.
function useMarket(sources: Source[], search: MarketSearch) {
  const [state, setState] = useState(EMPTY)
  const [inLibrary, setInLibrary] = useState<InLibrary>({})
  const key = JSON.stringify([search.q, search.shelf])
  // Bumped per search, so answers for an earlier one are dropped.
  const generation = useRef(0)

  const remember = (found: InLibrary) =>
    setInLibrary((prev) => ({ ...prev, ...found }))

  function browse(targets: Source[], cursors: Record<number, string>) {
    const gen = generation.current
    void Promise.all(
      targets.map((s) =>
        marketBrowse({
          data: {
            sourceId: s.id,
            q: search.q,
            shelf: search.shelf?.find((r) => r.source === s.id)?.id,
            cursor: cursors[s.id],
          },
        }).then(
          (view): Answer => ({ source: s, view, error: null }),
          (err): Answer => ({ source: s, view: null, error: message(err) }),
        ),
      ),
    ).then((answers) => {
      if (gen !== generation.current) return
      for (const a of answers) if (a.view) remember(a.view.inLibrary)
      setState((prev) => settle(prev, answers, search.q))
    })
  }

  useEffect(() => {
    generation.current++
    setState(EMPTY)
    browse(
      sources.filter((s) =>
        search.q
          ? s.searchable
          : !search.shelf || search.shelf.some((r) => r.source === s.id),
      ),
      {},
    )
    // `key` covers the search; sources only change on reload.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [key, sources])

  return {
    ...state,
    inLibrary,
    loadMore() {
      setState((prev) => ({ ...prev, loading: true }))
      browse(
        sources.filter((s) => state.cursors[s.id]),
        state.cursors,
      )
    },
    markAdded: (offer: SourceRef, bookId: string) =>
      remember({ [`${offer.source}:${offer.id}`]: bookId }),
  }
}

type Market = ReturnType<typeof useMarket>

const libraryId = (book: MergedBook, inLibrary: InLibrary) =>
  book.offers.map((o) => inLibrary[`${o.source}:${o.id}`]).find(Boolean)

function Market() {
  const sources = Route.useLoaderData()
  const search = Route.useSearch()
  const navigate = useNavigate({ from: Route.fullPath })
  const market = useMarket(sources, search)
  const loading = market.loading

  if (!sources.length) {
    return (
      <main className="mx-auto max-w-6xl px-4 py-8">
        <h1 className="text-2xl font-semibold">Market</h1>
        <div className="mt-6 flex min-h-72 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
          <Store className="size-8" />
          <p className="text-sm">No sources</p>
          <Button asChild variant="outline" size="sm">
            <Link to="/settings/market">Add a source</Link>
          </Button>
        </div>
      </main>
    )
  }

  const errors = market.errors

  return (
    <main className="mx-auto max-w-6xl px-4 py-8">
      <h1 className="text-2xl font-semibold">Market</h1>

      {sources.some((s) => s.searchable) && (
        <form
          key={search.q}
          className="relative mt-6"
          onSubmit={(e) => {
            e.preventDefault()
            const q = String(new FormData(e.currentTarget).get('q')).trim()
            void navigate({ search: { q: q || undefined } })
          }}
        >
          <Search className="pointer-events-none absolute top-1/2 left-4 size-5 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            name="q"
            placeholder="Search"
            aria-label="Search the Market"
            defaultValue={search.q}
            className="h-12 rounded-full pl-12 text-base md:text-base"
          />
          {loading && (
            <Loader2 className="absolute top-1/2 right-4 size-5 -translate-y-1/2 animate-spin text-muted-foreground" />
          )}
        </form>
      )}

      <div className="mt-8 grid gap-8">
        {errors.length > 0 && (
          <div className="grid gap-1">
            {errors.map((r) => (
              <p key={r.source} className="text-sm text-destructive">
                Could not load {r.sourceName}: {r.error}
              </p>
            ))}
          </div>
        )}
        {search.q || search.shelf ? (
          <ListingView market={market} multiSource={sources.length > 1} />
        ) : (
          <HomeView market={market} multiSource={sources.length > 1} />
        )}
      </div>
    </main>
  )
}

function Loading() {
  return (
    <div className="flex min-h-48 items-center justify-center text-muted-foreground">
      <Loader2 className="size-6 animate-spin" />
    </div>
  )
}

function HomeView({
  market,
  multiSource,
}: {
  market: Market
  multiSource: boolean
}) {
  if (!market.home) return market.loading ? <Loading /> : null
  const { rows, shelves } = market.home
  return (
    <div className="grid gap-10">
      {rows.map((row) => (
        <section
          key={row.refs.map((r) => `${r.source}:${r.id}`).join(' ')}
          className="min-w-0"
        >
          <div className="mb-4 flex items-baseline justify-between gap-3">
            <h2 className="text-xl font-semibold">{row.title}</h2>
            <Link
              to="/market"
              search={{ shelf: row.refs }}
              className="flex items-center text-sm text-muted-foreground hover:text-foreground"
            >
              See all
              <ChevronRight className="size-4" />
            </Link>
          </div>
          <ul className="-mx-4 flex snap-x scroll-px-4 gap-5 overflow-x-auto px-4 pb-2">
            {row.books.map((book) => (
              <li
                key={`${book.offers[0].source}:${book.offers[0].id}`}
                className="w-36 shrink-0 snap-start sm:w-40"
              >
                <BookCard
                  book={book}
                  market={market}
                  multiSource={multiSource}
                />
              </li>
            ))}
          </ul>
        </section>
      ))}
      {shelves.length > 0 && (
        <section>
          <h2 className="mb-4 text-xl font-semibold">Browse</h2>
          <ShelfGrid shelves={shelves} />
        </section>
      )}
    </div>
  )
}

function ListingView({
  market,
  multiSource,
}: {
  market: Market
  multiSource: boolean
}) {
  const search = Route.useSearch()
  const { books, shelves, loading } = market
  const title = search.q ?? market.title ?? 'Market'
  const hasMore = Object.keys(market.cursors).length > 0
  const empty = !books.length && !shelves.length

  return (
    <div className="grid gap-8">
      <nav className="flex min-w-0 items-center gap-1 text-sm text-muted-foreground">
        <Link to="/market" className="shrink-0 hover:text-foreground">
          Market
        </Link>
        <ChevronRight className="size-4 shrink-0" />
        <h2 className="truncate font-medium text-foreground">{title}</h2>
      </nav>

      {shelves.length > 0 && <ShelfGrid shelves={shelves} />}

      {empty && loading && <Loading />}
      {empty && !loading && (
        <div className="flex min-h-48 flex-col items-center justify-center gap-3 rounded-lg border border-dashed text-muted-foreground">
          <Search className="size-8" />
          <p className="text-sm">Nothing found</p>
        </div>
      )}

      {books.length > 0 && (
        <ul className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
          {books.map((book) => (
            <li key={`${book.offers[0].source}:${book.offers[0].id}`}>
              <BookCard book={book} market={market} multiSource={multiSource} />
            </li>
          ))}
        </ul>
      )}

      {hasMore && !empty && (
        <div className="flex justify-center">
          <Button
            variant="outline"
            onClick={market.loadMore}
            disabled={loading}
          >
            {loading && <Loader2 className="animate-spin" />}
            {loading ? 'Loading…' : 'Load more'}
          </Button>
        </div>
      )}
    </div>
  )
}

function ShelfGrid({ shelves }: { shelves: MergedShelf[] }) {
  return (
    <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
      {shelves.map((shelf) => (
        <li key={shelf.refs.map((r) => `${r.source}:${r.id}`).join(' ')}>
          <Link
            to="/market"
            search={{ shelf: shelf.refs }}
            className="group flex h-full items-center gap-3 rounded-xl border bg-card px-4 py-3.5 transition-colors hover:bg-accent"
          >
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium">{shelf.title}</p>
              {shelf.description && (
                <p className="mt-0.5 line-clamp-2 text-sm text-muted-foreground">
                  {shelf.description}
                </p>
              )}
            </div>
            <ChevronRight className="size-4 shrink-0 text-muted-foreground transition-transform group-hover:translate-x-0.5" />
          </Link>
        </li>
      ))}
    </ul>
  )
}

type AddState =
  | { status: 'idle' | 'adding' }
  | { status: 'added'; bookId: string }
  | { status: 'error'; message: string }

function formatSize(bytes: number | null) {
  if (!bytes) return null
  return bytes >= 1_000_000
    ? `${(bytes / 1_000_000).toFixed(1)} MB`
    : `${Math.max(1, Math.round(bytes / 1000))} KB`
}

// A book: the cover and title open its details; the button adds the best
// format from the first source that has one (the dialog lets you pick).
function BookCard({
  book,
  market,
  multiSource,
}: {
  book: MergedBook
  market: Market
  multiSource: boolean
}) {
  const [open, setOpen] = useState(false)
  const [local, setLocal] = useState<AddState>({ status: 'idle' })
  const libraryBookId = libraryId(book, market.inLibrary)
  const state: AddState = libraryBookId
    ? { status: 'added', bookId: libraryBookId }
    : local

  async function addOffer(offer: SourceRef, formatId: string) {
    const { bookId } = await marketAdd({
      data: { sourceId: offer.source, bookId: offer.id, formatId },
    })
    market.markAdded(offer, bookId)
  }

  // Tries each source in turn until one has an EPUB that downloads.
  async function add(choice?: SourceRef & { formatId: string }) {
    setLocal({ status: 'adding' })
    let error = 'No EPUB available'
    for (const offer of choice ? [choice] : book.offers) {
      try {
        const formatId =
          choice?.formatId ??
          (
            await marketBook({
              data: { sourceId: offer.source, bookId: offer.id },
            })
          ).book.formats[0]?.id
        if (!formatId) continue
        await addOffer(offer, formatId)
        setLocal({ status: 'idle' })
        return
      } catch (err) {
        error = message(err)
      }
    }
    setLocal({ status: 'error', message: error })
  }

  return (
    <div className="flex h-full flex-col">
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="group text-left"
      >
        <BookCover
          title={book.title}
          authors={book.authors}
          coverUrl={book.coverUrl}
          className="transition duration-200 group-hover:-translate-y-1 group-hover:shadow-lg"
        />
        <p className="mt-3 line-clamp-2 text-sm leading-snug font-medium">
          {book.title}
        </p>
        <p className="mt-0.5 line-clamp-1 text-xs text-muted-foreground">
          {book.authors.join(', ')}
        </p>
      </button>
      <div className="mt-auto pt-3">
        <AddButton
          state={state}
          onAdd={() => add()}
          size="sm"
          className="w-full"
        />
        {state.status === 'error' && (
          <p className="mt-1 text-xs text-destructive">{state.message}</p>
        )}
      </div>
      {open && (
        <BookDialog
          book={book}
          multiSource={multiSource}
          onClose={() => setOpen(false)}
          state={state}
          onInLibrary={market.markAdded}
          onAdd={add}
        />
      )}
    </div>
  )
}

function AddButton({
  state,
  onAdd,
  disabled,
  size,
  className,
}: {
  state: AddState
  onAdd: () => void
  disabled?: boolean
  size?: 'sm' | 'default'
  className?: string
}) {
  if (state.status === 'added') {
    return (
      <Button asChild variant="secondary" size={size} className={className}>
        <Link to="/books/$bookId" params={{ bookId: state.bookId }}>
          <Check />
          In library
        </Link>
      </Button>
    )
  }
  const adding = state.status === 'adding'
  return (
    <Button
      variant={size === 'sm' ? 'outline' : 'default'}
      size={size}
      className={className}
      disabled={adding || disabled}
      onClick={onAdd}
    >
      {adding ? <Loader2 className="animate-spin" /> : <Plus />}
      {adding ? 'Adding…' : 'Add to library'}
    </Button>
  )
}

type OfferDetails = {
  source: number
  sourceName: string
  id: string
  book: BookDetails | null
  error: string | null
}

// Loads the book's details from every source that has it when opened. Shows
// the first source's details and every source's formats.
function BookDialog({
  book,
  multiSource,
  onClose,
  state,
  onInLibrary,
  onAdd,
}: {
  book: MergedBook
  multiSource: boolean
  onClose: () => void
  state: AddState
  onInLibrary: (offer: SourceRef, bookId: string) => void
  onAdd: (offer: SourceRef & { formatId: string }) => void
}) {
  const [offers, setOffers] = useState<OfferDetails[] | null>(null)
  const [choice, setChoice] = useState<string>()
  // Reload only when the offers change, not on every merge of the list.
  const offersKey = book.offers.map((o) => `${o.source}:${o.id}`).join(' ')

  useEffect(() => {
    let current = true
    void Promise.all(
      book.offers.map(async (offer) => {
        try {
          const result = await marketBook({
            data: { sourceId: offer.source, bookId: offer.id },
          })
          if (result.libraryBookId && current) {
            onInLibrary(offer, result.libraryBookId)
          }
          return { ...offer, book: result.book, error: null }
        } catch (err) {
          return { ...offer, book: null, error: message(err) }
        }
      }),
    ).then((loaded) => {
      if (!current) return
      setOffers(loaded)
      const first = loaded.find((o) => o.book?.formats.length)
      // Keep the user's choice when the offers change, if it still exists.
      setChoice((prev) =>
        loaded.some((o) =>
          o.book?.formats.some((f) => `${o.source}|${f.id}` === prev),
        )
          ? prev
          : first && `${first.source}|${first.book!.formats[0].id}`,
      )
    })
    return () => {
      current = false
    }
    // onInLibrary is a fresh closure each render.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [offersKey])

  const details = offers?.find((o) => o.book)?.book
  const shown = details ?? book
  const formats = (offers ?? []).flatMap((o) =>
    (o.book?.formats ?? []).map((f) => ({
      ...f,
      key: `${o.source}|${f.id}`,
      offer: o,
      text: [multiSource && o.sourceName, f.label, formatSize(f.size)]
        .filter(Boolean)
        .join(' · '),
    })),
  )
  const format = formats.find((f) => f.key === choice)
  const added = state.status === 'added'
  const description = offers?.map((o) => o.book?.description).find(Boolean)
  const shelves = (offers ?? []).flatMap((o) =>
    (o.book?.shelves ?? []).map((s) => ({ ...s, source: o.source })),
  )

  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
        <div className="grid gap-6 sm:grid-cols-[180px_1fr]">
          <BookCover
            title={shown.title}
            authors={shown.authors}
            coverUrl={book.coverUrl ?? shown.coverUrl}
            className="mx-auto w-40 sm:w-full"
          />
          <div className="flex min-w-0 flex-col gap-4">
            <div className="grid gap-1 pr-6">
              <DialogTitle className="text-xl leading-tight">
                {shown.title}
              </DialogTitle>
              <DialogDescription>{shown.authors.join(', ')}</DialogDescription>
            </div>

            {!offers && (
              <Loader2 className="size-5 animate-spin text-muted-foreground" />
            )}
            {offers
              ?.filter((o) => o.error)
              .map((o) => (
                <p key={o.source} className="text-sm text-destructive">
                  Could not load {o.sourceName}: {o.error}
                </p>
              ))}

            {offers && formats.length === 0 && !added && (
              <p className="text-sm text-muted-foreground">No EPUB available</p>
            )}
            {offers && (formats.length > 0 || added) && (
              <>
                {formats.length > 1 && !added && (
                  <Select value={choice} onValueChange={setChoice}>
                    <SelectTrigger aria-label="Format" className="w-full">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {formats.map((f) => (
                        <SelectItem key={f.key} value={f.key}>
                          {f.text}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
                <div className="flex flex-wrap items-center gap-3">
                  <AddButton
                    state={state}
                    disabled={!format}
                    onAdd={() =>
                      format &&
                      onAdd({
                        source: format.offer.source,
                        id: format.offer.id,
                        formatId: format.id,
                      })
                    }
                  />
                  {formats.length === 1 && !added && (
                    <span className="text-sm text-muted-foreground">
                      {formats[0].text}
                    </span>
                  )}
                </div>
              </>
            )}
            {state.status === 'error' && (
              <p className="text-sm text-destructive">{state.message}</p>
            )}

            {description && (
              <p className="text-sm leading-relaxed whitespace-pre-line text-muted-foreground">
                {description}
              </p>
            )}

            {shelves.length > 0 && (
              <ul className="flex flex-wrap gap-2">
                {shelves.map((shelf) => (
                  <li key={`${shelf.source}:${shelf.id}`}>
                    <Link
                      to="/market"
                      search={{
                        shelf: [{ source: shelf.source, id: shelf.id }],
                      }}
                      onClick={onClose}
                      className="block rounded-full border px-3 py-1 text-xs transition-colors hover:bg-accent"
                    >
                      {shelf.title}
                    </Link>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}
# Market

The Market is built on pluggable integrations. Read `docs/market-integrations.md` before changing anything here or adding a store.

- Adding a store means adding an integration in `integrations/<id>.ts` that implements `MarketIntegration` from `sdk.ts`, registered in `INTEGRATIONS` in `host.ts`. Nothing else should change.
- Integrations import only from `#/lib/market/sdk` and fetch only through `ctx.fetch`.
- Store-specific code lives only in its integration. Never branch on an integration or source id in `host.ts`, `merge.ts`, `src/lib/market-functions.ts` or the Market UI.
- If an integration needs something the contract lacks, extend `sdk.ts` generically (an optional field or method the host and UI handle for every source), update the docs, and bump `apiVersion` if it breaks existing integrations.

import { createServerFn } from '@tanstack/react-start'
import { eq } from 'drizzle-orm'

import { db } from '#/db'
import { books } from '#/db/schema'
import { bookCard, bookView } from '#/lib/books'
import { bookKeys } from '#/lib/market/merge'
import {
  findHardcoverBook,
  hardcoverAuthor,
  hardcoverBookDetails,
  hardcoverEnabled,
  hardcoverSeries,
} from '#/lib/metadata/hardcover'
import type { HardcoverBook } from '#/lib/metadata/hardcover'
import { requireSession } from '#/lib/user-functions'
import { foldName } from '#/lib/utils'

// Author and series pages, and the Hardcover rows on book pages. The library
// half works offline; Hardcover adds what isn't in the library, and the
// `discover*` functions return null without a token or when it fails.

const name = (value: unknown) =>
  typeof value === 'string' ? value.trim().slice(0, 500) : ''

const libraryViews = () => db.select().from(books).all().map(bookView)

const bySortTitle = (a: { sortTitle: string }, b: { sortTitle: string }) =>
  a.sortTitle.localeCompare(b.sortTitle)

export const getAuthorBooks = createServerFn({ method: 'GET' })
  .validator(name)
  .handler(async ({ data: author }) => {
    await requireSession()
    const wanted = foldName(author)
    return libraryViews()
      .filter((b) => b.authors.some((a) => foldName(a) === wanted))
      .sort(bySortTitle)
      .map(bookCard)
  })

export const getSeriesBooks = createServerFn({ method: 'GET' })
  .validator(name)
  .handler(async ({ data: series }) => {
    await requireSession()
    const wanted = foldName(series)
    return libraryViews()
      .filter((b) => b.series && foldName(b.series) === wanted)
      .sort(
        (a, b) =>
          (a.seriesIndex ?? Infinity) - (b.seriesIndex ?? Infinity) ||
          bySortTitle(a, b),
      )
      .map((b) => ({ ...bookCard(b), seriesIndex: b.seriesIndex }))
  })

// A Hardcover book, and the library book that is the same work, if any.
export type DiscoverBook = HardcoverBook & { libraryId: string | null }

function libraryIndex() {
  const index = new Map<string, string>()
  for (const book of libraryViews()) {
    for (const key of bookKeys(book)) {
      if (!index.has(key)) index.set(key, book.id)
    }
  }
  return (book: HardcoverBook): DiscoverBook => ({
    ...book,
    libraryId:
      bookKeys({ ...book, isbn: null })
        .map((k) => index.get(k))
        .find(Boolean) ?? null,
  })
}

// Discovery fails softly: the page just leaves the Hardcover parts out.
async function soft<T>(what: string, load: () => Promise<T>) {
  if (!hardcoverEnabled()) return null
  try {
    return await load()
  } catch (err) {
    console.warn(`Hardcover ${what}:`, err instanceof Error ? err.message : err)
    return null
  }
}

export const discoverBook = createServerFn({ method: 'GET' })
  .validator((bookId: string) => name(bookId))
  .handler(async ({ data: bookId }) => {
    await requireSession()
    return soft('book', async () => {
      const row = db.select().from(books).where(eq(books.id, bookId)).get()
      if (!row) return null
      const book = bookView(row)
      const source = row.matched?.source
      const id = await findHardcoverBook(
        book,
        source?.provider === 'hardcover' ? source.id : undefined,
      )
      const details = id ? await hardcoverBookDetails(id) : null
      if (!id || !details) return null
      // Hardcover's spelling of the name, so the author search finds it.
      const authorName = details.author ?? book.authors[0]
      const author = authorName
        ? await hardcoverAuthor(authorName).catch(() => null)
        : null
      const link = libraryIndex()
      return {
        ...details,
        similar: details.similar.map(link),
        // Other books by the author, in the library or not, most read first.
        moreByAuthor: author && {
          name: author.name,
          books: author.books
            .filter((b) => b.id !== id)
            .map(link)
            .filter((b) => b.libraryId !== bookId)
            .slice(0, 12),
        },
      }
    })
  })

export const discoverAuthor = createServerFn({ method: 'GET' })
  .validator(name)
  .handler(async ({ data: authorName }) => {
    await requireSession()
    return soft('author', async () => {
      const author = await hardcoverAuthor(authorName)
      if (!author) return null
      const link = libraryIndex()
      return { ...author, books: author.books.map(link) }
    })
  })

export const discoverSeries = createServerFn({ method: 'GET' })
  .validator((data: { series: string; author: string | null }) => ({
    series: name(data.series),
    author: name(data.author) || null,
  }))
  .handler(async ({ data }) => {
    await requireSession()
    return soft('series', async () => {
      const series = await hardcoverSeries(data.series, data.author)
      if (!series) return null
      const views = libraryViews()
      const link = libraryIndex()
      // A library book with this series' name and the same number is that
      // book, even under another title ("The Sign of the Four").
      const wanted = foldName(data.series)
      const byPosition = new Map(
        views
          .filter((b) => b.series && foldName(b.series) === wanted)
          .map((b) => [b.seriesIndex, b.id]),
      )
      const linked = series.books.map((b) => {
        const book = link(b)
        return {
          ...book,
          libraryId: book.libraryId ?? byPosition.get(b.position) ?? null,
          position: b.position,
        }
      })
      // Library books Hardcover puts in the series, for those whose file
      // doesn't name it.
      const ids = new Set(linked.flatMap((b) => b.libraryId ?? []))
      const library = views
        .filter((b) => ids.has(b.id))
        .map((b) => ({
          ...bookCard(b),
          seriesIndex:
            linked.find((l) => l.libraryId === b.id)?.position ?? null,
        }))
      return { ...series, books: linked, library }
    })
  })
  },
}

type LibraryBook = { title: string; authors: string[]; isbn: string | null }

// The Hardcover id of a library book: the one it was matched to, else the
// first search result that is the same work (same ISBN, or title and author).
export function findHardcoverBook(book: LibraryBook, matchedId?: string) {
  if (matchedId && /^\d+$/.test(matchedId)) {
    return Promise.resolve(Number(matchedId))
  }
  const query = book.isbn || [book.title, book.authors[0] ?? ''].join(' ')
  return cached(`find:${query}`, async () => {
    const wanted = new Set(bookKeys(book))
    const docs = await searchBooks(query, 5)
    const doc = docs.find((d) =>
      [null, ...(d.isbns ?? [])].some((isbn) =>
        bookKeys({ title: d.title ?? '', authors: docAuthors(d), isbn }).some(
          (k) => wanted.has(k),
        ),
      ),
    )
    return doc ? Number(doc.id) : null
  })
}

type Tags = Record<string, Array<{ tag?: string }> | undefined>

export type HardcoverBookDetails = {
  url: string
  rating: number | null
  ratingsCount: number
  genres: string[]
  moods: string[]
  series: { name: string; position: number | null } | null
  author: string | null
  similar: HardcoverBook[]
}

export function hardcoverBookDetails(id: number) {
  return cached(
    `book:${id}`,
    async (): Promise<HardcoverBookDetails | null> => {
      const { book } = await gql<{
        book: {
          slug: string
          rating: number | null
          ratings_count: number
          cached_tags: Tags
          cached_similar_book_ids: number[]
          cached_contributors: Contributor[]
          book_series: Array<{
            position: number | null
            series: { name: string }
          }>
        } | null
      }>(
        `query($id: Int!) {
        book: books_by_pk(id: $id) {
          slug rating ratings_count cached_tags cached_similar_book_ids
          cached_contributors
          book_series(limit: 1, order_by: { featured: desc }) {
            position series { name }
          }
        }
      }`,
        { id },
      )
      if (!book) return null
      const ids = (book.cached_similar_book_ids ?? []).slice(0, 12)
      const similar = ids.length ? await booksById(ids) : []
      const tags = (key: string, limit: number) =>
        (book.cached_tags?.[key] ?? [])
          .slice(0, limit)
          .map((t) => t.tag ?? '')
          .filter(Boolean)
          .map((t) => t.charAt(0).toUpperCase() + t.slice(1))
      const series = book.book_series[0]
      return {
        url: `${SITE_URL}/books/${book.slug}`,
        rating: book.ratings_count ? book.rating : null,
        ratingsCount: book.ratings_count,
        genres: tags('Genre', 3),
        moods: tags('Mood', 2),
        series: series
          ? { name: series.series.name, position: series.position }
          : null,
        author: writers(book.cached_contributors)[0] ?? null,
        similar,
      }
    },
  )
}

// In the order of `ids`.
async function booksById(ids: number[]) {
  const { books } = await gql<{ books: BookRow[] }>(
    `query($ids: [Int!]!) {
      books(where: { id: { _in: $ids } }) { ${BOOK_FIELDS} }
    }`,
    { ids },
  )
  const byId = new Map(books.map((b) => [b.id, toBook(b)]))
  return ids.flatMap((id) => byId.get(id) ?? [])
}

export type HardcoverAuthor = {
  name: string
  url: string
  bio: string | null
  born: number | null
  died: number | null
  books: HardcoverBook[]
}

// The author with exactly this name (ignoring case and punctuation) and their
// most read books.
export function hardcoverAuthor(name: string) {
  return cached(`author:${fold(name)}`, async () => {
    const found = await gql<{
      search: {
        results?: { hits?: Array<{ document: { id: string; name: string } }> }
      }
    }>(
      `query($q: String!) {
        search(query: $q, query_type: "Author", per_page: 5) { results }
      }`,
      { q: name },
    )
    const hit = found.search.results?.hits?.find(
      (h) => fold(h.document.name) === fold(name),
    )
    if (!hit) return null
    const { author } = await gql<{
      author: {
        name: string
        slug: string
        bio: string | null
        born_year: number | null
        death_year: number | null
        contributions: Array<{ book: BookRow }>
      } | null
    }>(
      `query($id: Int!) {
        author: authors_by_pk(id: $id) {
          name slug bio born_year death_year
          contributions(
            where: {
              contributable_type: { _eq: "Book" }
              _or: [{ contribution: { _is_null: true } }, { contribution: { _eq: "Author" } }]
              book: { canonical_id: { _is_null: true }, compilation: { _eq: false } }
            }
            order_by: { book: { users_count: desc } }
            limit: 24
          ) { book { ${BOOK_FIELDS} } }
        }
      }`,
      { id: Number(hit.document.id) },
    )
    if (!author) return null
    return {
      name: author.name,
      url: `${SITE_URL}/authors/${author.slug}`,
      // Bios copied from Wikipedia keep its footnote marks: "[2][b]".
      bio: author.bio
        ? htmlToText(author.bio).replace(/\[\w{1,3}\]/g, '') || null
        : null,
      born: author.born_year,
      died: author.death_year,
      // One book per work: editions and retitlings are separate books.
      books: author.contributions
        .map((c) => toBook(c.book))
        .filter((book, i, all) => {
          const key = bookKeys({ ...book, isbn: null })[0]
          return (
            !key ||
            all.findIndex((b) => bookKeys({ ...b, isbn: null })[0] === key) ===
              i
